import{_ as s,C as n,o as e,c as o,a2 as a,b as d,w as l,a as i,E,a3 as g}from"./chunks/framework.CZGNF-7T.js";const b=JSON.parse('{"title":"캘린더 (Calendar)","description":"","frontmatter":{},"headers":[],"relativePath":"work-manage/calendar.md","filePath":"work-manage/calendar.md","lastUpdated":1788524367000}'),c={name:"work-manage/calendar.md"};function C(B,t,h,A,p,u){const r=n("Mermaid");return e(),o("div",null,[t[1]||(t[1]=a('<h1 id="캘린더-calendar" tabindex="-1">캘린더 (Calendar) <a class="header-anchor" href="#캘린더-calendar" aria-label="Permalink to &quot;캘린더 (Calendar)&quot;">​</a></h1><blockquote><p><strong>캘린더</strong> 모듈은 워크스페이스 내에서 발생하는 모든 **업무(Issue)**의 시작·완료 기한과 <strong>회의(Meeting)</strong> 일정을 월간 그리드 위에 시각화하여, 전사 및 프로젝트의 타임라인을 한눈에 조망할 수 있는 종합 일정 관리 화면입니다.</p></blockquote><h2 id="_1-개요-및-2대-운영-모드" tabindex="-1">1. 개요 및 2대 운영 모드 <a class="header-anchor" href="#_1-개요-및-2대-운영-모드" aria-label="Permalink to &quot;1. 개요 및 2대 운영 모드&quot;">​</a></h2><p>캘린더는 관리 범위에 따라 두 가지 관점으로 운영됩니다.</p><ul><li><strong>전사 통합 캘린더</strong>: 상단 메뉴의 **[캘린더]**를 통해 접근하며, 본인이 참여하는 모든 워크스페이스의 업무와 회의 일정을 종합 모니터링합니다.</li><li><strong>워크스페이스 캘린더</strong>: 개별 워크스페이스 내 <strong>[캘린더]</strong> 탭으로 접근하여, 해당 사업지나 부서의 마일스톤과 세부 작업 일정에 집중합니다.</li></ul>',5)),(e(),d(g,null,{default:l(()=>[E(r,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20subgraph%20%EC%9D%BC%EC%A0%95%EB%8D%B0%EC%9D%B4%ED%84%B0%20%5B%22%EC%9D%BC%EC%A0%95%20%EB%8D%B0%EC%9D%B4%ED%84%B0%20%EC%88%98%EC%A7%91%22%5D%0A%20%20%20%20%20%20%20%20A%5B%22%F0%9F%93%8B%20%EC%97%85%EB%AC%B4%20(%EC%8B%9C%EC%9E%91%EC%9D%BC%20~%20%EC%99%84%EB%A3%8C%EA%B8%B0%ED%95%9C)%22%5D%0A%20%20%20%20%20%20%20%20B%5B%22%F0%9F%A4%9D%20%ED%9A%8C%EC%9D%98%EB%A1%9D%20(%ED%9A%8C%EC%9D%98%20%EC%9D%BC%EC%8B%9C)%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20A%20--%3E%20C%5B%22%F0%9F%8E%A8%20%EC%83%81%ED%83%9C%EB%B3%84%20%EC%83%89%EC%83%81%20%EB%A7%A4%ED%95%91%3Cbr%3E(%EC%8B%A0%EA%B7%9C%C2%B7%EC%A7%84%ED%96%89%C2%B7%EC%A2%85%EB%A3%8C%20%EB%93%B1)%22%5D%0A%20%20%20%20B%20--%3E%20D%5B%22%F0%9F%9F%A3%20%ED%9A%8C%EC%9D%98%20%EC%A0%84%EC%9A%A9%20%EB%B3%B4%EB%9D%BC%EC%83%89%20%EB%A7%A4%ED%95%91%3Cbr%3E(%239575cd)%22%5D%0A%0A%20%20%20%20C%20%26%20D%20--%3E%20E%5B%22%F0%9F%93%85%20FullCalendar%20%EC%9B%94%EA%B0%84%20%EB%A0%8C%EB%8D%94%EB%A7%81%3Cbr%3E(%EC%98%A4%EB%8A%98%20%EC%95%8C%EB%A6%BC%20%EC%95%84%EC%9D%B4%EC%BD%98%20%EB%B6%80%EC%B0%A9)%22%5D%0A%20%20%20%20E%20--%3E%20F%5B%22%F0%9F%93%8A%20%ED%95%98%EB%8B%A8%20%ED%86%B5%EA%B3%84%20%EC%B9%B4%EB%93%9C%20(%EC%A0%84%EC%B2%B4%C2%B7%EC%A7%84%ED%96%89%EC%A4%91%C2%B7%EC%99%84%EB%A3%8C)%22%5D%0A"})]),fallback:l(()=>[...t[0]||(t[0]=[i(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a('<h2 id="_2-주요-기능-및-일정-시각화" tabindex="-1">2. 주요 기능 및 일정 시각화 <a class="header-anchor" href="#_2-주요-기능-및-일정-시각화" aria-label="Permalink to &quot;2. 주요 기능 및 일정 시각화&quot;">​</a></h2><h3 id="🎨-업무-상태-및-회의-구분-색상-다크모드-대응" tabindex="-1">🎨 업무 상태 및 회의 구분 색상 (다크모드 대응) <a class="header-anchor" href="#🎨-업무-상태-및-회의-구분-색상-다크모드-대응" aria-label="Permalink to &quot;🎨 업무 상태 및 회의 구분 색상 (다크모드 대응)&quot;">​</a></h3><p>일정 바(Bar)의 색상은 업무의 진행 상태와 회의 일정을 즉시 식별할 수 있도록 테마(Light/Dark)에 따라 최적화된 컬러로 자동 렌더링됩니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">구분</th><th style="text-align:center;">Light 테마 색상</th><th style="text-align:left;">Dark 테마 색상</th><th style="text-align:left;">설명</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>신규</strong></td><td style="text-align:center;"><span style="color:#e57373;">● #e57373</span></td><td style="text-align:left;"><span style="color:#b35c5c;">● #b35c5c</span></td><td style="text-align:left;">즉시 확인이 필요한 신규 등록 업무</td></tr><tr><td style="text-align:left;"><strong>진행</strong></td><td style="text-align:center;"><span style="color:#64b5f6;">● #64b5f6</span></td><td style="text-align:left;"><span style="color:#5c86b3;">● #5c86b3</span></td><td style="text-align:left;">현재 수행 중인 활성 작업</td></tr><tr><td style="text-align:left;"><strong>검토</strong></td><td style="text-align:center;"><span style="color:#ffb74d;">● #ffb74d</span></td><td style="text-align:left;"><span style="color:#b3915c;">● #b3915c</span></td><td style="text-align:left;">피드백 및 승인 대기 중인 업무</td></tr><tr><td style="text-align:left;"><strong>보류 / 거절</strong></td><td style="text-align:center;"><span style="color:#90a4ae;">● #90a4ae</span></td><td style="text-align:left;"><span style="color:#64748b;">● #64748b</span></td><td style="text-align:left;">일시 중지되거나 반려된 작업</td></tr><tr><td style="text-align:left;"><strong>종료</strong></td><td style="text-align:center;"><span style="color:#81c784;">● #81c784</span></td><td style="text-align:left;"><span style="color:#5cb377;">● #5cb377</span></td><td style="text-align:left;">완수되어 마감된 업무</td></tr><tr><td style="text-align:left;"><strong>회의록</strong></td><td style="text-align:center;"><span style="color:#9575cd;">● #9575cd</span></td><td style="text-align:left;"><span style="color:#9575cd;">● #9575cd</span></td><td style="text-align:left;">공식 회의 일정 (보라색 고정)</td></tr></tbody></table><h3 id="🔔-오늘의-일정-알림-아이콘" tabindex="-1">🔔 오늘의 일정 알림 아이콘 <a class="header-anchor" href="#🔔-오늘의-일정-알림-아이콘" aria-label="Permalink to &quot;🔔 오늘의 일정 알림 아이콘&quot;">​</a></h3><p>업무 타이틀 앞에는 **오늘(Today)**을 기준으로 마감 임박 상태를 직관적으로 경고하는 3대 상태 아이콘이 표시됩니다.</p><ul><li><i class="mdi mdi-arrow-right-bold text-success"></i> <strong>오늘 시작</strong>: 오늘부터 일정이 시작되는 업무 (녹색 화살표)</li><li><i class="mdi mdi-arrow-left-bold text-danger"></i> <strong>오늘 마감</strong>: 오늘까지 반드시 완료해야 하는 데드라인 업무 (붉은색 화살표)</li><li><i class="mdi mdi-rhombus text-danger"></i> <strong>당일 처리</strong>: 오늘 하루 동안 착수하고 종결해야 하는 1일 과업 (붉은색 다이아몬드)</li></ul><h3 id="🔍-복합-필터링-및-저장-쿼리-saved-queries" tabindex="-1">🔍 복합 필터링 및 저장 쿼리 (Saved Queries) <a class="header-anchor" href="#🔍-복합-필터링-및-저장-쿼리-saved-queries" aria-label="Permalink to &quot;🔍 복합 필터링 및 저장 쿼리 (Saved Queries)&quot;">​</a></h3><ul><li><strong>다차원 조건 검색</strong>: 상단 검색바를 통해 워크스페이스, 담당자, 업무 유형(Tracker), 상태뿐만 아니라 <strong>회의 카테고리</strong>까지 교차 필터링할 수 있습니다.</li><li><strong>저장 쿼리 사이드바</strong>: 자주 조회하는 일정 조합(예: <em>&quot;나의 이번 주 마감 업무&quot;</em>, <em>&quot;경영 회의 일정&quot;</em>)을 사이드바에 저장하여 원클릭으로 재호출합니다.</li></ul><h3 id="📊-실시간-현황-요약-카드" tabindex="-1">📊 실시간 현황 요약 카드 <a class="header-anchor" href="#📊-실시간-현황-요약-카드" aria-label="Permalink to &quot;📊 실시간 현황 요약 카드&quot;">​</a></h3><p>캘린더 하단에는 현재 화면에 표시된 업무들의 실시간 통계 카드가 제공됩니다.</p><ul><li><strong>전체 건수</strong>: 현재 월간 그리드에 필터링된 총 업무 수</li><li><strong>진행 중 / 완료 건수</strong>: 활성 업무와 종결 업무의 비중을 대조하여 이번 달의 목표 달성도를 평가할 수 있습니다.</li></ul><h2 id="_3-조작-및-연동-팁" tabindex="-1">3. 조작 및 연동 팁 <a class="header-anchor" href="#_3-조작-및-연동-팁" aria-label="Permalink to &quot;3. 조작 및 연동 팁&quot;">​</a></h2><ul><li><strong>원클릭 상세 이동</strong>: 캘린더의 일정 바를 클릭하면 해당 <strong><a href="/work-manage/issue.html">업무 상세</a></strong> 또는 <strong><a href="/work-manage/meeting.html">회의록 상세</a></strong> 페이지로 즉시 이동합니다.</li><li><strong>직관적인 타이틀 포맷</strong>: 업무는 <code>[유형] 제목 (담당자)</code>, 회의는 <code>제목</code> 형식으로 표출되어 상세 페이지를 열지 않고도 핵심 주체를 파악할 수 있습니다.</li><li><strong>오늘 위치 파악</strong>: 현재 날짜는 상단 날짜 셀이 굵은 파란색 배지로 강조되어 전체 타임라인 속 오늘의 위치를 쉽게 인지할 수 있습니다.</li></ul>',14))])}const x=s(c,[["render",C]]);export{b as __pageData,x as default};
